const W = $('Webhook consulta').first().json;
const b = W.body || {};
const cfg = $('Config').first().json;
const base = { message_id: String(b.message_id || ''), group_jid: String(b.group_jid || ''), dry: b.dry === true };
const strip = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
const USO = 'Como usar: */consulta [cliente] [período]*\nExemplos:\n• /consulta Alice Salazar outubro\n• /consulta Official Time mês atual\n• /consulta VS Med 01/11 a 10/11\n• /consulta Trufer últimos 7 dias\n\nPeríodos: nome do mês (outubro, out/2025), mês atual, mês passado, hoje, ontem, últimos N dias ou DD/MM a DD/MM. Sem período = mês atual até hoje.';

if (base.group_jid !== cfg.grupoAlfred) return [];
const linha = String(b.text || '').replace(/\r/g, '').split('\n')[0].trim().replace(/^[*_~`\s]+|[*_~`\s]+$/g, '');
const m = linha.match(/^\/consulta(?![A-Za-zÀ-ÿ0-9_])[*_~`\s]*(.*)$/i);
if (!m) return [];

const hoje = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Sao_Paulo' }).format(b.now_override ? new Date(b.now_override) : new Date());
const [Y, M, D] = hoje.split('-').map(Number);
const p2 = n => String(n).padStart(2, '0');
const iso = (y, mo, d) => y + '-' + p2(mo) + '-' + p2(d);
const addDays = (y, mo, d, n) => { const t = new Date(Date.UTC(y, mo - 1, d + n)); return [t.getUTCFullYear(), t.getUTCMonth() + 1, t.getUTCDate()]; };
const lastDay = (y, mo) => new Date(Date.UTC(y, mo, 0)).getUTCDate();
const MESES = ['janeiro', 'fevereiro', 'marco', 'abril', 'maio', 'junho', 'julho', 'agosto', 'setembro', 'outubro', 'novembro', 'dezembro'];
const NOMES = ['janeiro', 'fevereiro', 'março', 'abril', 'maio', 'junho', 'julho', 'agosto', 'setembro', 'outubro', 'novembro', 'dezembro'];
const ABREV = { jan: 1, fev: 2, mar: 3, abr: 4, mai: 5, jun: 6, jul: 7, ago: 8, set: 9, out: 10, nov: 11, dez: 12 };
const erro = msg => [{ json: { ...base, acao: 'responder', message: msg } }];

let rest = strip(m[1]).replace(/\s+/g, ' ').trim();
let per = null, mm;
const ano4 = a => (a ? (String(a).length === 2 ? 2000 + Number(a) : Number(a)) : null);

if ((mm = rest.match(/\b(\d{1,2})\/(\d{1,2})(?:\/(\d{2,4}))?\s*(?:a|ate|ao|-)\s*(\d{1,2})\/(\d{1,2})(?:\/(\d{2,4}))?$/))) {
  const y2 = ano4(mm[6]) || Y, y1 = ano4(mm[3]) || y2;
  per = { tipo: 'intervalo', y1, m1: +mm[2], d1: +mm[1], y2, m2: +mm[5], d2: +mm[4] };
  rest = rest.slice(0, mm.index);
} else if ((mm = rest.match(/\b(?:ultimos|ult)\.?\s*(\d{1,3})\s*dias?$/)) || (mm = rest.match(/\b(\d{1,3})\s*d$/))) {
  const n = Math.min(Math.max(+mm[1], 1), 365);
  const [y1, m1, d1] = addDays(Y, M, D, -(n - 1));
  per = { tipo: 'dias', n, y1, m1, d1, y2: Y, m2: M, d2: D };
  rest = rest.slice(0, mm.index);
} else if ((mm = rest.match(/\bhoje$/))) {
  per = { tipo: 'dia', rot: 'de hoje', y1: Y, m1: M, d1: D, y2: Y, m2: M, d2: D }; rest = rest.slice(0, mm.index);
} else if ((mm = rest.match(/\bontem$/))) {
  const [y, mo, d] = addDays(Y, M, D, -1);
  per = { tipo: 'dia', rot: 'de ontem', y1: y, m1: mo, d1: d, y2: y, m2: mo, d2: d }; rest = rest.slice(0, mm.index);
} else if ((mm = rest.match(/\b(?:mes atual|este mes|mes corrente|mes passado|mes anterior|ultimo mes)$/))) {
  const passado = /passado|anterior|ultimo/.test(mm[0]);
  per = { tipo: 'mes', y: passado ? (M === 1 ? Y - 1 : Y) : Y, mo: passado ? (M === 1 ? 12 : M - 1) : M };
  rest = rest.slice(0, mm.index);
} else if ((mm = rest.match(/\b(janeiro|fevereiro|marco|abril|maio|junho|julho|agosto|setembro|outubro|novembro|dezembro|jan|fev|mar|abr|mai|jun|jul|ago|set|out|nov|dez)(?:\s*(?:de|\/|-)?\s*(\d{4}))?$/))) {
  const mo = MESES.includes(mm[1]) ? MESES.indexOf(mm[1]) + 1 : ABREV[mm[1]];
  const y = mm[2] ? +mm[2] : (mo > M ? Y - 1 : Y);
  per = { tipo: 'mes', y, mo };
  rest = rest.slice(0, mm.index);
}
if (!per) per = { tipo: 'mes', y: Y, mo: M };

if (per.tipo === 'mes') {
  const atual = per.y === Y && per.mo === M;
  if (per.y > Y || (per.y === Y && per.mo > M)) return erro('Esse mês ainda não começou. Escolha o mês atual ou um anterior.');
  per.y1 = per.y; per.m1 = per.mo; per.d1 = 1; per.y2 = per.y; per.m2 = per.mo; per.d2 = atual ? D : lastDay(per.y, per.mo);
  per.parcial = atual; per.nomeMes = NOMES[per.mo - 1] + (per.y !== Y ? ' de ' + per.y : '');
}
const from = iso(per.y1, per.m1, per.d1), to = iso(per.y2, per.m2, per.d2);
if (from > to) return erro('A data inicial é depois da final. Use *DD/MM a DD/MM*.');
if (to > hoje) return erro('O período termina no futuro. O dash só tem dados até hoje (' + p2(D) + '/' + p2(M) + ').');
if (new Date(to) - new Date(from) > 366 * 86400000) return erro('Período muito longo (máximo 1 ano).');

const dd = (y, mo, d) => p2(d) + '/' + p2(mo);
let faixa;
if (per.y1 === per.y2 && per.m1 === per.m2) faixa = 'de ' + p2(per.d1) + ' a ' + dd(per.y2, per.m2, per.d2);
else faixa = 'de ' + dd(per.y1, per.m1, per.d1) + (per.y1 !== per.y2 ? '/' + per.y1 : '') + ' a ' + dd(per.y2, per.m2, per.d2) + (per.y1 !== per.y2 ? '/' + per.y2 : '');
let titulo;
if (per.tipo === 'mes') titulo = 'segue o resultado ' + (per.parcial ? 'parcial ' : '') + 'de ' + per.nomeMes + ', ' + faixa;
else if (per.tipo === 'dia') titulo = 'segue o resultado ' + per.rot + ', ' + dd(per.y2, per.m2, per.d2);
else if (per.tipo === 'dias') titulo = 'segue o resultado dos últimos ' + per.n + ' dias, ' + faixa;
else titulo = 'segue o resultado do período ' + faixa;

const query = rest.trim().replace(/\b(de|do|da|em|no|na|para|pro)$/, '').trim();
if (!query) return erro('Faltou o nome do cliente.\n\n' + USO);
return [{ json: { ...base, acao: 'seguir', query, from, to, titulo, parcial: per.tipo === 'mes' ? !!per.parcial : false } }];

const h = $input.first().json.headers || {};
let sc = h['set-cookie'];
if (!sc) throw new Error('O login do dash não devolveu cookie.');
const arr = Array.isArray(sc) ? sc : [sc];
return [{ json: { cookie: arr.map(c => c.split(';')[0]).join('; ') } }];

const t = $('Interpretar').first().json;
const norm = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9]/g, '');
let dash = $('Dash - lista de clientes').all().map(i => i.json);
if (dash.length === 1 && Array.isArray(dash[0].clients)) dash = dash[0].clients;
dash = dash.filter(c => c && c.id && c.name);
const q = norm(t.query);
let hits = dash.filter(c => norm(c.name) === q);
if (!hits.length) hits = dash.filter(c => norm(c.name).startsWith(q));
if (!hits.length && q.length >= 3) hits = dash.filter(c => norm(c.name).includes(q));
const resp = message => [{ json: { ...t, acao: 'responder', message } }];
if (!q) return resp('Faltou o nome do cliente.');
if (hits.length > 1) return resp('Encontrei mais de um cliente com "' + t.query + '":\n' + hits.slice(0, 8).map(c => '• ' + c.name).join('\n') + '\n\nEscreva o nome completo.');
if (!hits.length) return resp('Não encontrei "' + t.query + '" no dash.\n\nClientes disponíveis:\n' + dash.map(c => c.name).sort((a, b) => a.localeCompare(b, 'pt-BR')).slice(0, 40).map(n => '• ' + n).join('\n'));
return [{ json: { ...t, acao: 'consultar', dashClientId: hits[0].id, dashNome: hits[0].name } }];

const t = $('Casar cliente').first().json;
const r = $input.first().json;
const msg = message => [{ json: { ...t, message } }];
if (!r || !r.client) return msg('Não consegui ler os dados de ' + t.dashNome + ' no dash agora. Tente de novo em alguns minutos.');
const fmt = n => { const s = (Math.round((n + Number.EPSILON) * 100) / 100).toFixed(2); const [i, d] = s.split('.'); return i.replace(/\B(?=(\d{3})+(?!\d))/g, '.') + ',' + d; };
const brl = n => 'R$ ' + fmt(n);
const NOME = { google_ads: 'Google Ads', meta: 'Meta Ads', tiktok: 'TikTok Ads', linkedin: 'LinkedIn Ads', bing: 'Microsoft Ads', pinterest: 'Pinterest Ads', youtube: 'YouTube Ads', amazon: 'Amazon Ads' };
const nome = k => NOME[k] || (String(k).replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase()));

const ecom = r.client.businessType === 'ecommerce' || (r.hybrid === true && (r.store || (r.ecom && r.ecom.revenue > 0)));
let fat, vendas, funil = null; const porPlat = {};
if (ecom) {
  const cs = (r.campaigns || []).filter(c => c.segment === 'ecommerce' && c.stage !== 'reconhecimento');
  cs.forEach(c => { porPlat[c.platform] = (porPlat[c.platform] || 0) + (c.spend || 0); });
  const st = r.store, ec = r.ecom || {};
  vendas = st ? (st.orders || 0) : Math.round(ec.purchases || 0);
  fat = st ? (st.revenue || 0) : (ec.revenue || 0);
} else {
  Object.entries(r.platforms || {}).forEach(([k, p]) => { porPlat[k] = p.spendPerformance || 0; });
  const f = r.funnel || {};
  vendas = f.sales || 0; fat = f.revenue || 0;
  funil = { leads: f.leads || 0, mql: f.mql || 0, sql: f.sql || 0 };
}
const plats = Object.entries(porPlat).filter(([, v]) => v > 0).sort((a, b) => b[1] - a[1]);
const invest = plats.reduce((a, [, v]) => a + v, 0);
if (!fat && !invest && !vendas && !(funil && (funil.leads || funil.mql || funil.sql))) return msg('Sem dados de ' + t.dashNome + ' no dash para esse período (' + t.from.split('-').reverse().join('/') + ' a ' + t.to.split('-').reverse().join('/') + ').');

const roas = fat > 0 && invest > 0 ? fat / invest : 0;
const L = ['Pessoal, ' + t.titulo + ' 📊', ''];
if (fat > 0) L.push('💰 Faturamento: ' + brl(fat));
if (roas) L.push('📈 ROAS atualizado: ' + fmt(roas) + 'x');
if (invest > 0) { L.push('💵 Investimento em anúncios: ' + brl(invest)); plats.forEach(([k, v]) => L.push('* ' + nome(k) + ': ' + brl(v))); }
if (funil && (funil.leads || funil.mql || funil.sql)) {
  L.push('');
  if (funil.leads) L.push('👥 Leads: ' + funil.leads + (invest > 0 ? ' (CPL ' + brl(invest / funil.leads) + ')' : ''));
  if (funil.mql) L.push('🎯 MQLs: ' + funil.mql + (invest > 0 ? ' (custo por MQL ' + brl(invest / funil.mql) + ')' : ''));
  if (funil.sql) L.push('🤝 SQLs: ' + funil.sql + (invest > 0 ? ' (custo por SQL ' + brl(invest / funil.sql) + ')' : ''));
}
if (vendas > 0) { L.push(''); L.push('🛒 Tivemos ' + vendas + (vendas === 1 ? ' venda' : ' vendas') + (t.parcial ? ' até aqui.' : ' no período.')); }
if (roas) { L.push(''); L.push('Isso significa que, para cada R$ 1,00 investido em anúncios, tivemos aproximadamente R$ ' + fmt(roas) + ' em faturamento.  ⚙️✅'); }
return msg(L.join('\n'));
